pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        c.initialize();
        bool ok;
        try c.initialize() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Second initialize should revert");
    }
}
